<?php require 'config.php';admin_required();$rows=$pdo->query("SELECT u.id,u.name,u.email,u.phone,u.created_at,COUNT(l.id) loans FROM users u LEFT JOIN loans l ON l.user_id=u.id WHERE u.role='student' GROUP BY u.id ORDER BY u.name")->fetchAll();layout_start('Student members');?><section class="panel"><h2><?=count($rows)?> registered members</h2><div class="scroll"><table><tr><th>Name</th><th>Email</th><th>Phone</th><th>Loans</th><th>Joined</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['phone'])?></td><td><?=e($r['loans'])?></td><td><?=e(substr($r['created_at'],0,10))?></td></tr><?php endforeach;?></table></div></section><?php layout_end();?>